267	    /**
268	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
269	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
270	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
271	     *
272	     * @param ownerFieldsDto the submitted owner fields
273	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
274	     *                                     name of every offending field
275	     */
276	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
277	        List<String> missingFields = new ArrayList<>();
278	        if (isBlank(ownerFieldsDto.getFirstName())) {
279	            missingFields.add("firstName");
280	        }
281	        if (isBlank(ownerFieldsDto.getLastName())) {
282	            missingFields.add("lastName");
283	        }
284	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
285	            missingFields.add("address");
286	        }
287	        if (isBlank(ownerFieldsDto.getCity())) {
288	            missingFields.add("city");
289	        }
290	        if (isBlank(ownerFieldsDto.getTelephone())) {
291	            missingFields.add("telephone");
292	        }
293	        if (!missingFields.isEmpty()) {
294	            throw new InvalidOwnerFieldsException(missingFields);
295	        }
296	    }
